<script setup lang="ts">import { onMounted,ref } from 'vue';import { api } from '../api/client';import Panel from '../components/Panel.vue';import EmptyState from '../components/EmptyState.vue';import { money } from '../format';const data=ref<any>({samples:[],summary:{}});onMounted(async()=>{try{data.value=await api.experience()}catch{}});</script>
<template><div class="page-stack"><div class="kpi-grid five"><div class="kpi"><span>已完成样本</span><strong>{{data.summary?.completed??0}}</strong></div><div class="kpi"><span>盈利样本</span><strong class="positive">{{data.summary?.wins??0}}</strong></div><div class="kpi"><span>亏损样本</span><strong class="negative">{{data.summary?.losses??0}}</strong></div><div class="kpi"><span>胜率</span><strong>{{data.summary?.winRate==null?'未知':`${(data.summary.winRate*100).toFixed(1)}%`}}</strong></div><div class="kpi"><span>平均净收益</span><strong>{{money(data.summary?.avgNetPnl??0)}}</strong></div></div><Panel title="交易记忆" subtitle="只从本地 CLOSED TradeRecord 生成 Experience Sample；不拉取交易所外部历史"><table class="data-table"><thead><tr><th>Trade</th><th>Symbol</th><th>方向</th><th>Regime</th><th>净收益</th><th>结果</th><th>入场等待</th><th>教训</th></tr></thead><tbody><tr v-for="sample in data.samples??[]" :key="sample.sampleId"><td class="mono">{{sample.tradeId}}</td><td class="symbol">{{sample.symbol}}</td><td>{{sample.direction}}</td><td>{{sample.regime??'未知'}}</td><td :class="sample.netPnl>=0?'pos':'neg'">{{money(sample.netPnl)}}</td><td>{{sample.winLoss}}</td><td>{{sample.fillDelayMs==null?'未知':`${Math.round(sample.fillDelayMs/60000)}m`}}</td><td>{{sample.lesson}}</td></tr></tbody></table><EmptyState v-if="!data.samples?.length" title="尚无完成交易样本" detail="TradeRecord CLOSED 后会自动生成结构化交易记忆。"/></Panel></div></template>
